package com.guocheng.mediapocket;
import android.app.*;import android.content.SharedPreferences;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;import android.graphics.drawable.GradientDrawable;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** 添加、编辑 Emby 服务器，并按媒体库、剧集季、集浏览。 */
public final class EmbyLibraryActivity extends Activity {
 LinearLayout root,body;TextView status,title;SharedPreferences prefs;boolean light,dead;int epoch;ExecutorService io=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"emby-ui");t.setDaemon(true);return t;});Future<?> pending;ArrayDeque<Runnable> back=new ArrayDeque<>();
 interface Work {Runnable run()throws Exception;}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}int ink(){return light?0xff173740:0xfff5fafb;}int muted(){return light?0xff52757c:0xffafcbd2;}int surface(){return light?0xffedf5f5:0xff10343e;}int card(){return light?0xffffffff:0xff19434e;}
 GradientDrawable rounded(int color,int r){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(r));return d;}
 static void manage(android.content.Context c){android.content.Intent in=new android.content.Intent(c,EmbyLibraryActivity.class);in.putExtra("manage",true);c.startActivity(in);}
 static void open(android.content.Context c,JSONObject m){android.content.Intent in=new android.content.Intent(c,EmbyLibraryActivity.class);in.putExtra("server",m.optString("emby.server"));in.putExtra("item",m.optString("emby.item"));c.startActivity(in);}
 static void openLibrary(android.content.Context c,String server,String library){android.content.Intent in=new android.content.Intent(c,EmbyLibraryActivity.class);in.putExtra("server",server);in.putExtra("library",library);c.startActivity(in);}
 @Override public void onCreate(Bundle saved){prefs=getSharedPreferences("data",0);light=prefs.getString("themeMode","dark").equals("light");getTheme().applyStyle(light?android.R.style.Theme_Material_Light_NoActionBar:android.R.style.Theme_Material_NoActionBar,true);super.onCreate(saved);UiImages.configure(getCacheDir());getWindow().setStatusBarColor(surface());getWindow().setNavigationBarColor(surface());
  root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(surface());root.setPadding(dp(16),dp(8),dp(16),0);setContentView(root);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.addView(button("‹ 返回",()->onBackPressed()));title=text("Emby",18);title.setTypeface(null,1);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(header);status=text("",12);status.setTextColor(muted());root.addView(status);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,0,0,dp(28));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  String item=getIntent().getStringExtra("item"),library=getIntent().getStringExtra("library"),serverId=getIntent().getStringExtra("server");
  if(item!=null&&!item.isEmpty()){back.push(this::servers);detail(serverId,item);}
  else if(library!=null&&!library.isEmpty()){back.push(this::servers);library(serverId,library);}
  else if(getIntent().getBooleanExtra("manage",false)||EmbyStore.list(this).length()==0)servers();
  else libraries(EmbyStore.list(this).optJSONObject(0));
 }
 TextView text(String label,int size){TextView t=new TextView(this);t.setText(label);t.setTextSize(size);t.setTextColor(ink());t.setIncludeFontPadding(false);t.setPadding(0,dp(8),0,dp(8));return t;}
 Button button(String label,Runnable action){CinemaButton b=new CinemaButton(this,light);b.setText(label);b.setAllCaps(false);b.setBackground(rounded(card(),12));b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(card()));if(action!=null)b.setOnClickListener(v->action.run());return b;}
 void row(String label,Runnable action){Button b=button(label,action);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);body.addView(b,p);}
 void screen(String label){epoch++;if(pending!=null)pending.cancel(true);body.removeAllViews();title.setText(label);status.setText("");}
 void work(String label,Work task,Runnable retry){int token=++epoch;if(pending!=null)pending.cancel(true);status.setText(label);pending=io.submit(()->{try{Runnable done=task.run();runOnUiThread(()->{if(!dead&&token==epoch){status.setText("");done.run();}});}catch(Exception e){runOnUiThread(()->{if(dead||token!=epoch)return;status.setText(EmbyApi.explain(e));row("重试",retry);});}});}
 void push(Runnable destination,Runnable previous){back.push(previous);destination.run();}
 void servers(){screen("Emby 服务器");JSONArray all=EmbyStore.list(this);if(all.length()==0)body.addView(text("还没有服务器。填写地址和用户名，密码没有可留空。支持 http 或 https，端口可省略。",14));
  for(int i=0;i<all.length();i++){JSONObject s=all.optJSONObject(i);if(s==null)continue;String id=s.optString("id");row(EmbyStore.label(s),()->push(()->libraries(EmbyStore.get(this,id)),this::servers));LinearLayout actions=new LinearLayout(this);actions.addView(button("编辑",()->editor(EmbyStore.get(this,id))),new LinearLayout.LayoutParams(0,-2,1));actions.addView(button("删除",()->confirmDelete(id)),new LinearLayout.LayoutParams(0,-2,1));body.addView(actions);}body.addView(button("添加服务器",()->editor(null)));}
 void confirmDelete(String id){new AlertDialog.Builder(this).setTitle("删除这个 Emby 服务器？").setMessage("只从本机移除登录信息，不会改动服务器上的媒体。").setNegativeButton("取消",null).setPositiveButton("删除",(d,n)->{EmbyStore.delete(this,id);servers();}).show();}
 void editor(JSONObject existing){screen(existing==null?"添加服务器":"编辑服务器");EditText url=field(existing==null?"http://192.168.1.10:8096":existing.optString("url"),EmbyApi.serverHint());EditText user=field(existing==null?"":existing.optString("username"),"用户名");EditText pass=field("",EmbyApi.passwordHint(existing!=null));pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);EditText backup=field(backupText(existing),"备用地址，每行一个。主线路连不上时自动尝试");backup.setSingleLine(false);backup.setMinLines(2);body.addView(url);body.addView(user);body.addView(pass);body.addView(backup);
  body.addView(text("登录会请求 /Users/AuthenticateByName。令牌只保存在本机。",12));((TextView)body.getChildAt(body.getChildCount()-1)).setTextColor(muted());
  body.addView(button("登录并保存",()->{String address=url.getText().toString().trim(),name=user.getText().toString().trim(),password=pass.getText().toString();if(name.isEmpty()){user.setError("请填写用户名");return;}JSONArray backups;try{backups=EmbyCue.parseBackups(backup.getText().toString());for(int i=0;i<backups.length();i++)EmbyApi.server(backups.optString(i));}catch(Exception e){backup.setError(e.getMessage()==null?"备用地址无效":e.getMessage());return;}String secret=EmbyApi.loginPassword(existing!=null,password,existing==null?"":existing.optString("password"));JSONObject draft=existing==null?new JSONObject():existing;try{draft.put("url",address).put("backups",backups);}catch(Exception ignored){}
   work("正在登录…",()->{EmbyClient.authenticate(this,draft,name,secret);EmbyStore.save(this,draft);return ()->{Toast.makeText(this,"已保存 "+EmbyStore.label(draft),Toast.LENGTH_SHORT).show();servers();};},()->editor(existing));}));}
 static String backupText(JSONObject server){JSONArray list=server==null?null:server.optJSONArray("backups");if(list==null||list.length()==0)return "";StringBuilder s=new StringBuilder();for(int i=0;i<list.length();i++){if(i>0)s.append('\n');s.append(list.optString(i));}return s.toString();}
 EditText field(String value,String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setText(value);e.setHint(hint);e.setTextColor(ink());e.setHintTextColor(muted());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(6);e.setLayoutParams(p);return e;}
 void libraries(JSONObject server){if(server==null){servers();return;}screen(server.optString("name","Emby"));work("正在读取媒体库…",()->{JSONArray items=EmbyClient.views(this,server).optJSONArray("Items");return ()->{status.setText(EmbyStore.label(server));if(items==null||items.length()==0){body.addView(text("这个账号没有可浏览的媒体库",14));return;}for(int i=0;i<items.length();i++){JSONObject v=items.optJSONObject(i);if(v==null||!EmbyApi.library(v))continue;String id=v.optString("Id"),name=v.optString("Name","媒体库");boolean hidden=EmbyCue.hidden(server,id);row((hidden?"已隐藏 · ":"")+name,()->push(()->library(server.optString("id"),id),()->libraries(EmbyStore.get(this,server.optString("id")))));String sid=server.optString("id");body.addView(button(hidden?"显示这个媒体库":"在首页隐藏",()->{try{JSONObject current=EmbyStore.get(this,sid);if(current==null)return;current.put("hidden",EmbyCue.toggleHidden(current.optJSONArray("hidden"),id));EmbyStore.save(this,current);libraries(EmbyStore.get(this,sid));}catch(Exception ignored){}}));}};},()->libraries(server));}
 void library(String serverId,String libraryId){library(serverId,libraryId,"",false);}
 void library(String serverId,String libraryId,String genre,boolean favorite){JSONObject server=EmbyStore.get(this,serverId);if(server==null){servers();return;}screen("媒体库");work("正在读取条目…",()->{JSONObject folder=EmbyClient.item(this,server,libraryId);String types="movies".equals(folder.optString("CollectionType"))?"Movie":"tvshows".equals(folder.optString("CollectionType"))?"Series":"Movie,Series";JSONObject page=EmbyClient.items(this,server,libraryId,types,0,genre,favorite);JSONArray items=page.optJSONArray("Items");int total=page.optInt("TotalRecordCount",items==null?0:items.length());JSONArray genres=new JSONArray();try{JSONArray found=EmbyClient.genres(this,server,libraryId).optJSONArray("Items");if(found!=null)genres=found;}catch(Exception ignored){}JSONArray chips=genres;return ()->{title.setText(folder.optString("Name","媒体库"));filters(serverId,libraryId,chips,genre,favorite);if(items==null||items.length()==0)body.addView(text(favorite?"收藏里暂时没有条目":"此媒体库暂时没有条目",14));else gallery(server,items,()->library(serverId,libraryId,genre,favorite));more(server,libraryId,types,items==null?0:items.length(),total,serverId,genre,favorite);};},()->library(serverId,libraryId,genre,favorite));}
 void filters(String serverId,String libraryId,JSONArray genres,String genre,boolean favorite){HorizontalScrollView scroller=new HorizontalScrollView(this);scroller.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);scroller.addView(row);chip(row,"全部",genre.isEmpty()&&!favorite,()->library(serverId,libraryId,"",false));chip(row,"收藏",favorite,()->library(serverId,libraryId,"",true));for(int i=0;genres!=null&&i<genres.length()&&i<24;i++){JSONObject g=genres.optJSONObject(i);String name=g==null?"":g.optString("Name");if(name.isEmpty())continue;chip(row,name,name.equals(genre),()->library(serverId,libraryId,name,false));}body.addView(scroller);}
 void chip(LinearLayout row,String label,boolean on,Runnable action){Button b=button(label,action);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(on?(light?0xffcee4ef:0xff315c7a):card()));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(36));lp.rightMargin=dp(8);row.addView(b,lp);}
 /** 媒体库分页：每页 100 条，点「加载更多」接着往下排。筛选条件保持不变。 */
 void more(JSONObject server,String libraryId,String types,int loaded,int total,String serverId,String genre,boolean favorite){if(loaded<=0||loaded>=total)return;Button b=button("加载更多（已显示 "+loaded+" / "+total+"）",null);b.setOnClickListener(v->{b.setEnabled(false);b.setText("正在加载…");int token=epoch;io.submit(()->{try{JSONArray next=EmbyClient.items(this,server,libraryId,types,loaded,genre,favorite).optJSONArray("Items");runOnUiThread(()->{if(dead||token!=epoch)return;body.removeView(b);gallery(server,next,()->library(serverId,libraryId,genre,favorite));more(server,libraryId,types,loaded+(next==null?0:next.length()),next==null||next.length()==0?loaded:total,serverId,genre,favorite);});}catch(Exception e){runOnUiThread(()->{if(dead||token!=epoch)return;b.setEnabled(true);b.setText("加载失败，点此重试 · "+EmbyApi.explain(e));});}});});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(8);body.addView(b,p);}
 void detail(String serverId,String itemId){JSONObject server=EmbyStore.get(this,serverId);if(server==null){servers();return;}screen("影片");work("正在读取详情…",()->{JSONObject item=EmbyClient.item(this,server,itemId);String type=item.optString("Type");JSONArray seasons="Series".equals(type)?EmbyClient.seasons(this,server,itemId).optJSONArray("Items"):null;return ()->renderDetail(server,item,seasons);},()->detail(serverId,itemId));}
 void renderDetail(JSONObject server,JSONObject item,JSONArray seasons){try{JSONObject meta=EmbyApi.meta(server,item);title.setText(meta.optString("name"));FrameLayout hero=new FrameLayout(this);hero.setBackground(rounded(card(),12));hero.setClipToOutline(true);ImageView cover=new ImageView(this);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);hero.addView(cover,new FrameLayout.LayoutParams(-1,-1));TvPosterImages.load(this,cover,meta.optString("background",meta.optString("poster")),dp(800));body.addView(hero,new LinearLayout.LayoutParams(-1,Math.min(dp(280),(int)(getResources().getDisplayMetrics().widthPixels*.56f))));
  String facts=HomeRules.heroFacts(meta);if(!facts.isEmpty())body.addView(text(facts,13));String runtime=meta.optString("runtime");if(!runtime.isEmpty())body.addView(text("时长 "+runtime,13));String overview=meta.optString("description");body.addView(text(overview.isEmpty()?"暂无简介":overview,14));
  String type=item.optString("Type");if("Movie".equals(type)||"Episode".equals(type)){String play=meta.optLong("emby.resumeMs")>10000?"继续播放":"播放";body.addView(button(play,()->EmbyPlayback.playItem(this,server,item.optString("Id"))));}
  if("Series".equals(type)){body.addView(text("分季",16));if(seasons==null||seasons.length()==0)body.addView(text("没有季信息，直接列出全部剧集",13));else for(int i=0;i<seasons.length();i++){JSONObject season=seasons.optJSONObject(i);if(season==null)continue;String name=season.optString("Name","第 "+season.optInt("IndexNumber",i+1)+" 季");row(name,()->push(()->episodes(server,item.optString("Id"),season.optString("Id"),name),()->detail(server.optString("id"),item.optString("Id"))));}if(seasons==null||seasons.length()==0)episodes(server,item.optString("Id"),"","");}
 }catch(Exception e){status.setText(EmbyApi.explain(e));}}
 void episodes(JSONObject server,String seriesId,String seasonId,String name){if(!name.isEmpty())screen(name);work(name.isEmpty()?"正在读取剧集…":"正在读取 "+name+" …",()->{JSONArray items=EmbyClient.episodesAll(this,server,seriesId,seasonId);return ()->{if(!name.isEmpty())title.setText(name);if(items==null||items.length()==0){body.addView(text("这一季暂时没有剧集",14));return;}for(int i=0;i<items.length();i++){JSONObject ep=items.optJSONObject(i);if(ep==null)continue;String label=EmbyApi.line(ep);if(label.isEmpty())label=ep.optString("Name","剧集");String id=ep.optString("Id");row(label,()->EmbyPlayback.playItem(this,server,id));}};},()->episodes(server,seriesId,seasonId,name));}
 void gallery(JSONObject server,JSONArray list,Runnable retry){if(list==null||list.length()==0){body.addView(text("此媒体库暂时没有条目",14));return;}int available=getResources().getDisplayMetrics().widthPixels-dp(32),columns=Math.max(3,Math.min(6,available/dp(140))),width=(available-dp(10)*(columns-1))/columns;LinearLayout line=null;
  for(int i=0;i<Math.min(list.length(),300);i++){JSONObject v=list.optJSONObject(i);if(v==null||v.optString("Id").isEmpty())continue;if(line==null||line.getChildCount()==columns){line=new LinearLayout(this);line.setGravity(Gravity.TOP);body.addView(line);}LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);FrameLayout frame=new FrameLayout(this);frame.setBackground(rounded(card(),10));frame.setClipToOutline(true);tile.addView(frame,new LinearLayout.LayoutParams(width,(int)(width*1.5)));ImageView pic=new ImageView(this);pic.setScaleType(ImageView.ScaleType.CENTER_CROP);frame.addView(pic,new FrameLayout.LayoutParams(-1,-1));try{JSONObject meta=EmbyApi.meta(server,v);TvPosterImages.load(this,pic,meta.optString("poster"),width);TextView name=text(meta.optString("name"),12);name.setMaxLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);tile.addView(name);String id=v.optString("Id"),serverId=server.optString("id");tile.setOnClickListener(x->push(()->detail(serverId,id),retry));}catch(Exception ignored){}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(width,-2);lp.rightMargin=dp(10);lp.bottomMargin=dp(12);line.addView(tile,lp);}}
 @Override public void onBackPressed(){epoch++;if(pending!=null)pending.cancel(true);if(!back.isEmpty())back.pop().run();else super.onBackPressed();}
 @Override protected void onDestroy(){dead=true;epoch++;io.shutdownNow();super.onDestroy();}
}
